116	    /**
117	     * Add routes to a context using a lambda expression. It can be used as following:
118	     *
119	     * <pre>
120	     * RouteBuilder.addRoutes(context, rb ->
121	     *     rb.from("direct:inbound").bean(MyBean.class)));
122	     * </pre>
123	     *
124	     * @param  context   the camel context to add routes
125	     * @param  rbc       a lambda expression receiving the {@code RouteBuilder} to use to create routes
126	     * @throws Exception if an error occurs
127	     */
128	    public static void addRoutes(CamelContext context, LambdaRouteBuilder rbc) throws Exception {
129	        context.addRoutes(new RouteBuilder(context) {
130	            @Override
131	            public void configure() throws Exception {
132	                rbc.accept(this);
133	            }
134	        });
135	    }
