898	    protected void checkInitialized() throws Exception {
899	        if (initialized.compareAndSet(false, true)) {
900	            CamelContext camelContext = getContext();
901	            initializeCamelContext(camelContext);
902	
903	            List<RouteBuilderLifecycleStrategy> strategies = new ArrayList<>(lifecycleInterceptors);
904	            strategies.addAll(camelContext.getRegistry().findByType(RouteBuilderLifecycleStrategy.class));
905	            strategies.sort(Comparator.comparing(Ordered::getOrder));
906	
907	            for (RouteBuilderLifecycleStrategy interceptor : strategies) {
908	                interceptor.beforeConfigure(this);
909	            }
910	
911	            configure();
912	
913	            // remember the source resource
914	            getRouteCollection().setResource(getResource());
915	            getRestCollection().setResource(getResource());
916	            getRouteTemplateCollection().setResource(getResource());
917	            getTemplatedRouteCollection().setResource(getResource());
918	            for (BeanFactoryDefinition def : beans) {
919	                def.setResource(getResource());
920	            }
921	
922	            for (RouteDefinition route : getRouteCollection().getRoutes()) {
923	                // ensure the route is prepared after configure method is complete
924	                getRouteCollection().prepareRoute(route);
925	            }
926	
927	            for (RouteBuilderLifecycleStrategy interceptor : strategies) {
928	                interceptor.afterConfigure(this);
929	            }
930	        }
931	    }
