646	    private void doStartRouteDefinitions(List<RouteDefinition> routeDefinitions) throws Exception {
647	        PropertiesComponent pc = getCamelContextReference().getPropertiesComponent();
648	        // route templates supports binding beans that are local for the template only
649	        // in this local mode then we need to check for side-effects (see further)
650	        LocalBeanRepositoryAware localBeans = null;
651	        final Registry registry = getCamelContextReference().getRegistry();
652	        if (registry instanceof LocalBeanRepositoryAware localBeanRepositoryAware) {
653	            localBeans = localBeanRepositoryAware;
654	        }
655	        RouteDefinitionHelper.forceAssignIds(getCamelContextReference(), routeDefinitions);
656	        List<RouteDefinition> routeDefinitionsToRemove = null;
657	        for (RouteDefinition routeDefinition : routeDefinitions) {
658	            try {
659	                // assign ids to the routes and validate that the id's is all unique
660	                String duplicate = RouteDefinitionHelper.validateUniqueIds(routeDefinition, routeDefinitions,
661	                        routeDefinition.getNodePrefixId());
662	                if (duplicate != null) {
663	                    throw new FailedToStartRouteException(
664	                            routeDefinition.getId(),
665	                            "Duplicate id detected: " + duplicate
666	                                                     + ". Please correct ids to be unique among all your routes.");
667	                }
668	
669	                // if the route definition was created via a route template then we need to
670	                // prepare its parameters when the route is being created and started
671	                if (routeDefinition.isTemplate() != null && routeDefinition.isTemplate()
672	                        && routeDefinition.getTemplateParameters() != null) {
673	
674	                    // apply configurer if any present
675	                    if (routeDefinition.getRouteTemplateContext().getConfigurer() != null) {
676	                        routeDefinition.getRouteTemplateContext().getConfigurer()
677	                                .accept(routeDefinition.getRouteTemplateContext());
678	                    }
679	
680	                    // copy parameters/bean repository to not cause side effect
681	                    Map<String, Object> params = new HashMap<>(routeDefinition.getTemplateParameters());
682	                    LocalBeanRegistry bbr = (LocalBeanRegistry) routeDefinition.getRouteTemplateContext()
683	                            .getLocalBeanRepository();
684	                    LocalBeanRegistry bbrCopy = new LocalBeanRegistry();
685	
686	                    // make all bean in the bean repository use unique keys (need to add uuid
687	                    // counter)
688	                    // so when the route template is used again to create another route, then there
689	                    // is
690	                    // no side-effect from previously used values that Camel may use in its endpoint
691	                    // registry and elsewhere
692	                    if (bbr != null && !bbr.isEmpty()) {
693	                        Map<String, String> beanNameMappings = new HashMap<>();
694	                        for (Map.Entry<String, Object> param : params.entrySet()) {
695	                            Object value = param.getValue();
696	                            if (value instanceof String oldKey) {
697	                                boolean clash = bbr.keys().stream().anyMatch(k -> k.equals(oldKey));
698	                                if (clash) {
699	                                    String newKey = oldKey + "-" + UUID.generateUuid();
700	                                    LOG.debug(
701	                                            "Route: {} re-assigning local-bean id: {} to: {} to ensure ids are globally unique",
702	                                            routeDefinition.getId(), oldKey, newKey);
703	                                    bbrCopy.put(newKey, bbr.remove(oldKey));
704	                                    param.setValue(newKey);
705	                                    beanNameMappings.put(oldKey, newKey);
706	                                }
707	                            }
708	                        }
709	                        // ensure bean names removed during clash detection are still
710	                        // available as template parameters so they can be referenced
711	                        // directly in routes via {{beanName}}
712	                        for (Map.Entry<String, String> mapping : beanNameMappings.entrySet()) {
713	                            if (!params.containsKey(mapping.getKey())) {
714	                                params.put(mapping.getKey(), mapping.getValue());
715	                            }
716	                        }
717	                        // the remainder of the local beans must also have their ids made global unique
718	                        for (Map.Entry<String, Map<Class<?>, Object>> entry : bbr.entrySet()) {
719	                            String oldKey = entry.getKey();
720	                            String newKey = oldKey + "-" + UUID.generateUuid();
721	                            LOG.debug(
722	                                    "Route: {} re-assigning local-bean id: {} to: {} to ensure ids are globally unique",
723	                                    routeDefinition.getId(), oldKey, newKey);
724	                            bbrCopy.put(newKey, entry.getValue());
725	                            if (!params.containsKey(oldKey)) {
726	                                // if a bean was bound as local bean with a key and it was not defined as
727	                                // template parameter
728	                                // then store it as if it was a template parameter with same key=value which
729	                                // allows us
730	                                // to use this local bean in the route without any problem such as:
731	                                // to("bean:{{myBean}}")
732	                                // and myBean is the local bean id.
733	                                params.put(oldKey, newKey);
734	                            }
735	                        }
736	                    }
737	
738	                    OrderedLocationProperties prop = new OrderedLocationProperties();
739	                    if (routeDefinition.getTemplateDefaultParameters() != null) {
740	                        // need to keep track if a parameter is set as default value or end user
741	                        // configured value
742	                        params.forEach((k, v) -> {
743	                            Object dv = routeDefinition.getTemplateDefaultParameters().get(k);
744	                            prop.put(routeDefinition.getLocation(), k, v, dv);
745	                        });
746	                    } else {
747	                        prop.putAll(routeDefinition.getLocation(), params);
748	                    }
749	                    pc.setLocalProperties(prop);
750	
751	                    // we need to shadow the bean registry on the CamelContext with the local beans
752	                    // from the route template context
753	                    if (localBeans != null) {
754	                        localBeans.setLocalBeanRepository(bbrCopy);
755	                    }
756	
757	                    // need to reset auto assigned ids, so there is no clash when creating routes
758	                    ProcessorDefinitionHelper.resetAllAutoAssignedNodeIds(routeDefinition);
759	                    // must re-init parent when created from a template
760	                    RouteDefinitionHelper.initParent(routeDefinition);
761	                }
762	                // Check if the route is included
763	                if (includedRoute(routeDefinition)) {
764	                    // must ensure route is prepared, before we can start it
765	                    if (!routeDefinition.isPrepared()) {
766	                        RouteDefinitionHelper.prepareRoute(getCamelContextReference(), routeDefinition);
767	                        routeDefinition.markPrepared();
768	                    }
769	                    // force the creation of ids on all nodes in the route
770	                    RouteDefinitionHelper.forceAssignIds(this, routeDefinition.getInput());
771	                    RouteDefinitionHelper.forceAssignIds(this, routeDefinition);
772	
